1	import * as fs from 'node:fs';
2	import * as path from 'node:path';
3	import type { ILogger } from '@babamba2/mcp-abap-adt-interfaces';
4	import { createAdtClient } from '../../../lib/clients';
5	import type { HandlerContext } from '../../../lib/handlers/interfaces';
6	import {
7	  isLegacyUnsupported,
8	  legacyTableRead,
9	  parseSimpleSelect,
10	} from '../../../lib/legacyTableRead';
11	import {
12	  activeProfile,
13	  checkTables,
14	  evaluateHits,
15	  extractTablesFromSql,
16	  isAggregateOnly,
17	} from '../../../lib/policy/tableBlocklist';
18	import { safeOutputPath } from '../../../lib/sourceOutput';
19	import { ErrorCode, McpError } from '../../../lib/utils';
20	import { writeResultToFile } from '../../../lib/writeResultToFile';
21	import { decodeXmlEntities } from '../../../lib/xmlEntities';
22	export const TOOL_DEFINITION = {
23	  name: 'GetSqlQuery',
24	  available_in: ['onprem', 'cloud'] as const,
25	  description:
26	    '[read-only] Execute ABAP SQL SELECT queries on database tables and CDS views via SAP ADT Data Preview API. Use for ad-hoc data retrieval, row counts, and filtered queries.',
27	  inputSchema: {
28	    type: 'object',
29	    properties: {
30	      sql_query: {
31	        type: 'string',
32	        description: 'SQL query to execute',
33	      },
34	      row_number: {
35	        type: 'number',
36	        description: 'Maximum number of rows to return',
37	        default: 100,
38	      },
39	      output: {
40	        type: 'string',
41	        enum: ['inline', 'file'],
42	        default: 'inline',
43	        description:
44	          '"inline" (default) returns the rows. "file" writes the rows as JSON under the MCP output dir (sql/<table>-<time>.json) and returns only the path, row count, column names and the truncated flag. Prefer "file" for large result sets.',
45	      },
46	      acknowledge_risk: {
47	        type: 'boolean',
48	        description:
49	          "Set to true ONLY after the user has explicitly authorized row extraction from an 'ask'-tier protected table. The approval is logged to stderr for audit. Has no effect on 'deny'-tier tables.",
50	        default: false,
51	      },
52	    },
53	    required: ['sql_query'],
54	  },
55	} as const;
56	
57	/**
58	 * Interface for SQL query execution response
59	 */
60	export interface SqlQueryResponse {
61	  sql_query: string;
62	  row_number: number;
63	  execution_time?: number;
64	  total_rows?: number;
65	  columns: Array<{
66	    name: string;
67	    type: string;
68	    description?: string;
69	    length?: number;
70	  }>;
71	  rows: Array<Record<string, any>>;
72	  /** true when ADT returned more rows than requested (rows were cut to row_number) */
73	  truncated?: boolean;
74	}
75	
76	/**
77	 * One cell per <dataPreview:data> element. ADT writes an empty cell as a
78	 * self-closing <dataPreview:data/>; that form must count as a cell, or every
79	 * later value in the column moves up one row.
80	 */
81	const CELL_RE =
82	  /<dataPreview:data\b[^>]*?(?:\/>|>([\s\S]*?)<\/dataPreview:data>)/g;
83	
84	/**
85	 * Parse SAP ADT XML response from freestyle SQL query and convert to JSON format
86	 * @param xmlData - Raw XML response from ADT
87	 * @param sqlQuery - Original SQL query
88	 * @param rowNumber - Number of rows requested
89	 * @returns Parsed SQL query response
90	 */
91	export function parseSqlQueryXml(
92	  xmlData: string,
93	  sqlQuery: string,
94	  rowNumber: number,
95	  logger?: ILogger,
96	): SqlQueryResponse {
97	  try {
98	    // Extract basic information
99	    const totalRowsMatch = xmlData.match(
100	      /<dataPreview:totalRows>(\d+)<\/dataPreview:totalRows>/,
101	    );
102	    const totalRows = totalRowsMatch ? parseInt(totalRowsMatch[1], 10) : 0;
103	
104	    const queryTimeMatch = xmlData.match(
105	      /<dataPreview:queryExecutionTime>([\d.]+)<\/dataPreview:queryExecutionTime>/,
106	    );
107	    const queryExecutionTime = queryTimeMatch
108	      ? parseFloat(queryTimeMatch[1])
109	      : 0;
110	
111	    // Extract column metadata
112	    const columns: Array<{
113	      name: string;
114	      type: string;
115	      description?: string;
116	      length?: number;
117	    }> = [];
118	    const columnMatches = xmlData.match(/<dataPreview:metadata[^>]*>/g);
119	
120	    if (columnMatches) {
121	      columnMatches.forEach((match) => {
122	        const nameMatch = match.match(/dataPreview:name="([^"]+)"/);
123	        const typeMatch = match.match(/dataPreview:type="([^"]+)"/);
124	        const descMatch = match.match(/dataPreview:description="([^"]+)"/);
125	        const description = descMatch ? decodeXmlEntities(descMatch[1]) : '';
126	        const lengthMatch = match.match(/dataPreview:length="(\d+)"/);
127	
128	        if (nameMatch) {
129	          columns.push({
130	            name: nameMatch[1],
131	            type: typeMatch ? typeMatch[1] : 'UNKNOWN',
132	            description,
133	            length: lengthMatch ? parseInt(lengthMatch[1], 10) : undefined,
134	          });
135	        }
136	      });
137	    }
138	
139	    // Extract row data
140	    const rows: Array<Record<string, any>> = [];
141	    let truncated = false;
142	
143	    // Find all column sections
144	    const columnSections = xmlData.match(
145	      /<dataPreview:columns>.*?<\/dataPreview:columns>/gs,
146	    );
147	
148	    if (columnSections && columnSections.length > 0) {
149	      // Extract data for each column
150	      const columnData: Record<string, (string | null)[]> = {};
151	
152	      columnSections.forEach((section, index) => {
153	        if (index < columns.length) {
154	          const columnName = columns[index].name;
155	          columnData[columnName] = Array.from(section.matchAll(CELL_RE), (m) =>
156	            m[1] ? decodeXmlEntities(m[1]) : null,
157	          );
158	        }
159	      });
160	
161	      // Convert column-based data to row-based data
162	      const maxRowCount = Math.max(
163	        ...Object.values(columnData).map((arr) => arr.length),
164	        0,
165	      );
166	
167	      // ADT's data preview can return one row more than rowNumber.
168	      const rowCount = Math.min(maxRowCount, rowNumber);
169	      for (let rowIndex = 0; rowIndex < rowCount; rowIndex++) {
170	        const row: Record<string, any> = {};
171	        columns.forEach((column) => {
172	          const columnValues = columnData[column.name] || [];
173	          row[column.name] = columnValues[rowIndex] ?? null;
174	        });
175	        rows.push(row);
176	      }
177	      truncated = maxRowCount > rowNumber;
178	    }
179	
180	    return {
181	      sql_query: sqlQuery,
182	      row_number: rowNumber,
183	      execution_time: queryExecutionTime,
184	      total_rows: totalRows,
185	      columns,
186	      rows,
187	      ...(truncated ? { truncated } : {}),
188	    };
189	  } catch (parseError) {
190	    logger?.error('Failed to parse SQL query XML:', parseError as any);
191	
192	    // Return basic structure on parse error
193	    return {
194	      sql_query: sqlQuery,
195	      row_number: rowNumber,
196	      columns: [],
197	      rows: [],
198	      error: 'Failed to parse XML response',
199	    } as any;
200	  }
201	}
202	
203	/**
204	 * output: "file" — write the parsed result under <output root>/sql/ and return
205	 * a short summary instead of the rows. Same file shape on every path
206	 * (ADT data preview and the legacy TABLE_READ fallback).
207	 */
208	export function sqlResultToFile(
209	  parsed: Record<string, any>,
210	): Record<string, any> {
211	  const table = (
212	    extractTablesFromSql(String(parsed.sql_query ?? ''))[0] ?? 'query'
213	  )
214	    .toLowerCase()
215	    .replace(/[^a-z0-9_]/g, '_');
216	  const stamp = new Date()
217	    .toISOString()
218	    .replace(/[-:.TZ]/g, '')
219	    .slice(0, 17);
220	  const rand = Math.random().toString(36).slice(2, 6);
221	  const target = safeOutputPath(
222	    path.join('sql', `${table}-${stamp}-${rand}.json`),
223	  );
224	  fs.mkdirSync(path.dirname(target), { recursive: true });
225	  fs.writeFileSync(target, JSON.stringify(parsed), 'utf8');
226	  const rows = Array.isArray(parsed.rows) ? parsed.rows.length : 0;
227	  return {
228	    output: 'file',
229	    path: target,
230	    rows,
231	    columns: Array.isArray(parsed.columns)
232	      ? parsed.columns.map((c: any) => c?.name ?? c)
233	      : [],
234	    truncated: parsed.truncated === true,
235	    ...(parsed.path ? { source_path: parsed.path } : {}),
236	  };
237	}
238	
239	const sqlText = (args: any, parsed: Record<string, any>) =>
240	  JSON.stringify(args?.output === 'file' ? sqlResultToFile(parsed) : parsed);
241	
242	/**
243	 * Handler to execute freestyle SQL queries via SAP ADT Data Preview API
244	 *
245	 * @param args - Tool arguments containing sql_query and optional row_number parameter
246	 * @returns Response with parsed SQL query results or error
247	 */
248	export async function handleGetSqlQuery(context: HandlerContext, args: any) {
249	  const { connection, logger } = context;
250	  try {
251	    logger?.info('handleGetSqlQuery called');
252	
253	    if (!args?.sql_query) {
254	      throw new McpError(ErrorCode.InvalidParams, 'SQL query is required');
255	    }
256	
257	    const sqlQuery = args.sql_query;
258	    const rowNumber = args.row_number || 100; // Default to 100 rows if not specified
259	
260	    const tables = extractTablesFromSql(sqlQuery);
261	    if (tables.length > 0 && !isAggregateOnly(sqlQuery)) {
262	      const hits = checkTables(tables);
263	      const verdict = evaluateHits(
264	        hits,
265	        args.acknowledge_risk === true,
266	        activeProfile(),
267	      );
268	      if (verdict.kind === 'deny') {
269	        logger?.warn(`Blocked GetSqlQuery: ${tables.join(',')}`);
270	        throw new McpError(ErrorCode.InvalidRequest, verdict.message);
271	      }
272	      if (verdict.kind === 'ask') {
273	        logger?.warn(
274	          `GetSqlQuery requires user acknowledgement: ${tables.join(',')}`,
275	        );
276	        throw new McpError(ErrorCode.InvalidRequest, verdict.message);
277	      }
278	      if (verdict.kind === 'approved') {
279	        process.stderr.write(
280	          `[mcp-abap-adt][blocklist] AUDIT: user-acknowledged GetSqlQuery on ${verdict.tables.join(',')}\n`,
281	        );
282	        logger?.warn(
283	          `AUDIT: user-acknowledged GetSqlQuery on ${verdict.tables.join(',')}`,
284	        );
285	      }
286	    }
287	
288	    logger?.info(`Executing SQL query (rows=${rowNumber})`);
289	
290	    const client = createAdtClient(connection, logger);
291	    let response: any;
292	    try {
293	      response = await client
294	        .getUtils()
295	        .getSqlQuery({ sql_query: sqlQuery, row_number: rowNumber });
296	    } catch (e) {
297	      // BASIS < 7.50 has no freestyle data preview: answer a single-table
298	      // SELECT on an allow-listed table through ZMCP_ADT_DISPATCH TABLE_READ.
299	      if (!isLegacyUnsupported(e)) throw e;
300	      const simple = parseSimpleSelect(sqlQuery);
301	      if (!simple) {
302	        throw new Error(
303	          `${(e as Error).message} Fallback (ZMCP_ADT_DISPATCH TABLE_READ) handles only single-table SELECT … FROM … WHERE … — no JOIN, UNION, GROUP BY or aggregates.`,
304	        );
305	      }
306	      logger?.info(`Legacy fallback: TABLE_READ ${simple.table}`);
307	      const parsed = await legacyTableRead(connection, {
308	        ...simple,
309	        maxRows: rowNumber,
310	        sqlQuery,
311	      });
312	      return {
313	        isError: false,
314	        content: [
315	          {
316	            type: 'text',
317	            text: sqlText(args, {
318	              ...parsed,
319	              path: 'ecc-dispatch-table-read',
320	            }),
321	          },
322	        ],
323	      };
324	    }
325	
326	    if (response.status === 200 && response.data) {
327	      logger?.info('SQL query request completed successfully');
328	
329	      // Parse the XML response
330	      const parsedData = parseSqlQueryXml(
331	        response.data,
332	        sqlQuery,
333	        rowNumber,
334	        logger,
335	      );
336	
337	      logger?.debug(
338	        `Parsed SQL query data: rows=${parsedData.rows.length}/${parsedData.total_rows ?? 0}, columns=${parsedData.columns.length}`,
339	      );
340	
341	      const result = {
342	        isError: false,
343	        content: [
344	          {
345	            type: 'text',
346	            text: sqlText(args, parsedData),
347	          },
348	        ],
349	      };
350	      if (args.filePath) {
351	        logger?.debug(`Writing SQL query result to file: ${args.filePath}`);
352	        writeResultToFile(result, args.filePath);
353	      }
354	      return result;
355	    } else {
356	      throw new McpError(
357	        ErrorCode.InternalError,
358	        `Failed to execute SQL query. Status: ${response.status}`,
359	      );
360	    }
361	  } catch (error) {
362	    logger?.error('Failed to execute SQL query', error as any);
363	    // MCP-compliant error response: always return content[] with type "text"
364	    return {
365	      isError: true,
366	      content: [
367	        {
368	          type: 'text',
369	          text: `ADT error: ${String(error)}`,
370	        },
371	      ],
372	    };
373	  }
374	}
375

