import * as fs from 'node:fs';
import * as path from 'node:path';
import type { ILogger } from '@babamba2/mcp-abap-adt-interfaces';
import { createAdtClient } from '../../../lib/clients';
import type { HandlerContext } from '../../../lib/handlers/interfaces';
import {
  isLegacyUnsupported,
  legacyTableRead,
  parseSimpleSelect,
} from '../../../lib/legacyTableRead';
import {
  activeProfile,
  checkTables,
  evaluateHits,
  extractTablesFromSql,
  isAggregateOnly,
} from '../../../lib/policy/tableBlocklist';
import { safeOutputPath } from '../../../lib/sourceOutput';
import { ErrorCode, McpError } from '../../../lib/utils';
import { writeResultToFile } from '../../../lib/writeResultToFile';
import { decodeXmlEntities } from '../../../lib/xmlEntities';
export const TOOL_DEFINITION = {
  name: 'GetSqlQuery',
  available_in: ['onprem', 'cloud'] as const,
  description:
    '[read-only] Execute ABAP SQL SELECT queries on database tables and CDS views via SAP ADT Data Preview API. Use for ad-hoc data retrieval, row counts, and filtered queries.',
  inputSchema: {
    type: 'object',
    properties: {
      sql_query: {
        type: 'string',
        description: 'SQL query to execute',
      },
      row_number: {
        type: 'number',
        description: 'Maximum number of rows to return',
        default: 100,
      },
      output: {
        type: 'string',
        enum: ['inline', 'file'],
        default: 'inline',
        description:
          '"inline" (default) returns the rows. "file" writes the rows as JSON under the MCP output dir (sql/<table>-<time>.json) and returns only the path, row count, column names and the truncated flag. Prefer "file" for large result sets.',
      },
      acknowledge_risk: {
        type: 'boolean',
        description:
          "Set to true ONLY after the user has explicitly authorized row extraction from an 'ask'-tier protected table. The approval is logged to stderr for audit. Has no effect on 'deny'-tier tables.",
        default: false,
      },
    },
    required: ['sql_query'],
  },
} as const;

/**
 * Interface for SQL query execution response
 */
export interface SqlQueryResponse {
  sql_query: string;
  row_number: number;
  execution_time?: number;
  total_rows?: number;
  columns: Array<{
    name: string;
    type: string;
    description?: string;
    length?: number;
  }>;
  rows: Array<Record<string, any>>;
  /** true when ADT returned more rows than requested (rows were cut to row_number) */
  truncated?: boolean;
}

/**
 * One cell per <dataPreview:data> element. ADT writes an empty cell as a
 * self-closing <dataPreview:data/>; that form must count as a cell, or every
 * later value in the column moves up one row.
 */
const CELL_RE =
  /<dataPreview:data\b[^>]*?(?:\/>|>([\s\S]*?)<\/dataPreview:data>)/g;

/**
 * Parse SAP ADT XML response from freestyle SQL query and convert to JSON format
 * @param xmlData - Raw XML response from ADT
 * @param sqlQuery - Original SQL query
 * @param rowNumber - Number of rows requested
 * @returns Parsed SQL query response
 */
export function parseSqlQueryXml(
  xmlData: string,
  sqlQuery: string,
  rowNumber: number,
  logger?: ILogger,
): SqlQueryResponse {
  try {
    // Extract basic information
    const totalRowsMatch = xmlData.match(
      /<dataPreview:totalRows>(\d+)<\/dataPreview:totalRows>/,
    );
    const totalRows = totalRowsMatch ? parseInt(totalRowsMatch[1], 10) : 0;

    const queryTimeMatch = xmlData.match(
      /<dataPreview:queryExecutionTime>([\d.]+)<\/dataPreview:queryExecutionTime>/,
    );
    const queryExecutionTime = queryTimeMatch
      ? parseFloat(queryTimeMatch[1])
      : 0;

    // Extract column metadata
    const columns: Array<{
      name: string;
      type: string;
      description?: string;
      length?: number;
    }> = [];
    const columnMatches = xmlData.match(/<dataPreview:metadata[^>]*>/g);

    if (columnMatches) {
      columnMatches.forEach((match) => {
        const nameMatch = match.match(/dataPreview:name="([^"]+)"/);
        const typeMatch = match.match(/dataPreview:type="([^"]+)"/);
        const descMatch = match.match(/dataPreview:description="([^"]+)"/);
        const description = descMatch ? decodeXmlEntities(descMatch[1]) : '';
        const lengthMatch = match.match(/dataPreview:length="(\d+)"/);

        if (nameMatch) {
          columns.push({
            name: nameMatch[1],
            type: typeMatch ? typeMatch[1] : 'UNKNOWN',
            description,
            length: lengthMatch ? parseInt(lengthMatch[1], 10) : undefined,
          });
        }
      });
    }

    // Extract row data
    const rows: Array<Record<string, any>> = [];
    let truncated = false;

    // Find all column sections
    const columnSections = xmlData.match(
      /<dataPreview:columns>.*?<\/dataPreview:columns>/gs,
    );

    if (columnSections && columnSections.length > 0) {
      // Extract data for each column
      const columnData: Record<string, (string | null)[]> = {};

      columnSections.forEach((section, index) => {
        if (index < columns.length) {
          const columnName = columns[index].name;
          columnData[columnName] = Array.from(section.matchAll(CELL_RE), (m) =>
            m[1] ? decodeXmlEntities(m[1]) : null,
          );
        }
      });

      // Convert column-based data to row-based data
      const maxRowCount = Math.max(
        ...Object.values(columnData).map((arr) => arr.length),
        0,
      );

      // ADT's data preview can return one row more than rowNumber.
      const rowCount = Math.min(maxRowCount, rowNumber);
      for (let rowIndex = 0; rowIndex < rowCount; rowIndex++) {
        const row: Record<string, any> = {};
        columns.forEach((column) => {
          const columnValues = columnData[column.name] || [];
          row[column.name] = columnValues[rowIndex] ?? null;
        });
        rows.push(row);
      }
      truncated = maxRowCount > rowNumber;
    }

    return {
      sql_query: sqlQuery,
      row_number: rowNumber,
      execution_time: queryExecutionTime,
      total_rows: totalRows,
      columns,
      rows,
      ...(truncated ? { truncated } : {}),
    };
  } catch (parseError) {
    logger?.error('Failed to parse SQL query XML:', parseError as any);

    // Return basic structure on parse error
    return {
      sql_query: sqlQuery,
      row_number: rowNumber,
      columns: [],
      rows: [],
      error: 'Failed to parse XML response',
    } as any;
  }
}

/**
 * output: "file" — write the parsed result under <output root>/sql/ and return
 * a short summary instead of the rows. Same file shape on every path
 * (ADT data preview and the legacy TABLE_READ fallback).
 */
export function sqlResultToFile(
  parsed: Record<string, any>,
): Record<string, any> {
  const table = (
    extractTablesFromSql(String(parsed.sql_query ?? ''))[0] ?? 'query'
  )
    .toLowerCase()
    .replace(/[^a-z0-9_]/g, '_');
  const stamp = new Date()
    .toISOString()
    .replace(/[-:.TZ]/g, '')
    .slice(0, 17);
  const rand = Math.random().toString(36).slice(2, 6);
  const target = safeOutputPath(
    path.join('sql', `${table}-${stamp}-${rand}.json`),
  );
  fs.mkdirSync(path.dirname(target), { recursive: true });
  fs.writeFileSync(target, JSON.stringify(parsed), 'utf8');
  const rows = Array.isArray(parsed.rows) ? parsed.rows.length : 0;
  return {
    output: 'file',
    path: target,
    rows,
    columns: Array.isArray(parsed.columns)
      ? parsed.columns.map((c: any) => c?.name ?? c)
      : [],
    truncated: parsed.truncated === true,
    ...(parsed.path ? { source_path: parsed.path } : {}),
  };
}

const sqlText = (args: any, parsed: Record<string, any>) =>
  JSON.stringify(args?.output === 'file' ? sqlResultToFile(parsed) : parsed);

/**
 * Handler to execute freestyle SQL queries via SAP ADT Data Preview API
 *
 * @param args - Tool arguments containing sql_query and optional row_number parameter
 * @returns Response with parsed SQL query results or error
 */
export async function handleGetSqlQuery(context: HandlerContext, args: any) {
  const { connection, logger } = context;
  try {
    logger?.info('handleGetSqlQuery called');

    if (!args?.sql_query) {
      throw new McpError(ErrorCode.InvalidParams, 'SQL query is required');
    }

    const sqlQuery = args.sql_query;
    const rowNumber = args.row_number || 100; // Default to 100 rows if not specified

    const tables = extractTablesFromSql(sqlQuery);
    if (tables.length > 0 && !isAggregateOnly(sqlQuery)) {
      const hits = checkTables(tables);
      const verdict = evaluateHits(
        hits,
        args.acknowledge_risk === true,
        activeProfile(),
      );
      if (verdict.kind === 'deny') {
        logger?.warn(`Blocked GetSqlQuery: ${tables.join(',')}`);
        throw new McpError(ErrorCode.InvalidRequest, verdict.message);
      }
      if (verdict.kind === 'ask') {
        logger?.warn(
          `GetSqlQuery requires user acknowledgement: ${tables.join(',')}`,
        );
        throw new McpError(ErrorCode.InvalidRequest, verdict.message);
      }
      if (verdict.kind === 'approved') {
        process.stderr.write(
          `[mcp-abap-adt][blocklist] AUDIT: user-acknowledged GetSqlQuery on ${verdict.tables.join(',')}\n`,
        );
        logger?.warn(
          `AUDIT: user-acknowledged GetSqlQuery on ${verdict.tables.join(',')}`,
        );
      }
    }

    logger?.info(`Executing SQL query (rows=${rowNumber})`);

    const client = createAdtClient(connection, logger);
    let response: any;
    try {
      response = await client
        .getUtils()
        .getSqlQuery({ sql_query: sqlQuery, row_number: rowNumber });
    } catch (e) {
      // BASIS < 7.50 has no freestyle data preview: answer a single-table
      // SELECT on an allow-listed table through ZMCP_ADT_DISPATCH TABLE_READ.
      if (!isLegacyUnsupported(e)) throw e;
      const simple = parseSimpleSelect(sqlQuery);
      if (!simple) {
        throw new Error(
          `${(e as Error).message} Fallback (ZMCP_ADT_DISPATCH TABLE_READ) handles only single-table SELECT … FROM … WHERE … — no JOIN, UNION, GROUP BY or aggregates.`,
        );
      }
      logger?.info(`Legacy fallback: TABLE_READ ${simple.table}`);
      const parsed = await legacyTableRead(connection, {
        ...simple,
        maxRows: rowNumber,
        sqlQuery,
      });
      return {
        isError: false,
        content: [
          {
            type: 'text',
            text: sqlText(args, {
              ...parsed,
              path: 'ecc-dispatch-table-read',
            }),
          },
        ],
      };
    }

    if (response.status === 200 && response.data) {
      logger?.info('SQL query request completed successfully');

      // Parse the XML response
      const parsedData = parseSqlQueryXml(
        response.data,
        sqlQuery,
        rowNumber,
        logger,
      );

      logger?.debug(
        `Parsed SQL query data: rows=${parsedData.rows.length}/${parsedData.total_rows ?? 0}, columns=${parsedData.columns.length}`,
      );

      const result = {
        isError: false,
        content: [
          {
            type: 'text',
            text: sqlText(args, parsedData),
          },
        ],
      };
      if (args.filePath) {
        logger?.debug(`Writing SQL query result to file: ${args.filePath}`);
        writeResultToFile(result, args.filePath);
      }
      return result;
    } else {
      throw new McpError(
        ErrorCode.InternalError,
        `Failed to execute SQL query. Status: ${response.status}`,
      );
    }
  } catch (error) {
    logger?.error('Failed to execute SQL query', error as any);
    // MCP-compliant error response: always return content[] with type "text"
    return {
      isError: true,
      content: [
        {
          type: 'text',
          text: `ADT error: ${String(error)}`,
        },
      ],
    };
  }
}

