 *   TTREE      header   ID = menu name, TYPE = 'BMENU', MASTERLANG
 *   TMENU01    nodes    TREE_ID = menu, NODE_ID / PARENT_ID / BROTHER_ID,
 *                       NODE_TYPE NULL = folder, TCOD = t-code, AMRF = link to
 *                       another area menu
