export function normalizeModel(model) {
  const m = { ...model };
  m.lang = m.lang || 'ko';
  m.modules = arr(m.modules).length ? m.modules : [m.module].filter(Boolean);
  m.scope = { packages: [], tcodes: [], ...(m.scope || {}) };
  const systems = arr(m.scope.systems);
  m.scope.systems = [...systems, ...DEFAULT_SYSTEMS.filter(d => !systems.some(s => s.id === d.id))];
  m.lanes = arr(m.lanes);
  m.rows = arr(m.rows).map(r => ({
    ...r,
    code: String(r.code ?? ''),
    level: Number(r.level) || segs(r.code).length,
    tcodes: arr(r.tcodes), objects: arr(r.objects), variants: arr(r.variants),
  }));
  m.crossModule = arr(m.crossModule);
  m.openQuestions = arr(m.openQuestions);
  m.glossary = arr(m.glossary);
  m.notEvidenced = arr(m.notEvidenced);
  return m;
}
  app.push(`<div${m.glossary.length ? '' : ' class="ed-empty"'}><h3 id="gl">${esc(T.glossary)}</h3><div class="tw"><table><thead><tr><th>${esc(T.term)}</th><th>${esc(T.meaning)}</th><th class="ed-only
    + `${edList(E, 'm|glossary', 'term', m.glossary, (g, i) => `<td>${ed(`m|glossary.${i}.term`, g.term)}</td><td>${ed(`m|glossary.${i}.description`, g.description)}</td>`, { tag: 'tbody', row: 'tr' }
    + `<button type="button" class="edadd ed-only" data-add="m|glossary">${esc(E.add)}</button></div>`);
  {
    const xs = moduleSection(integrations, m, T, 4);
    if (xs) { toc.push(['xmodule', `4. ${T.xScen}`]); sec.push(xs); }
    const an = xs ? 5 : 4;
    toc.push(['appendix', `${an}. ${T.appendix}`]);
    sec.push(`<section id="appendix" class="page-break"><h2>${an}. ${esc(T.appendix)}</h2>${app.join('')}</section>`);
  }

