// Area menu view of the process page (model.menu written by area-menu.mjs --apply).
// Appendix section: summary counts, gap list (used + in menu, no task yet), menu tree by top folder with
// usage and the task codes each TCode belongs to, used TCodes no menu carries. Task sheet: menu path line.
import { anchorId } from './process-model.mjs';

const arr = (v) => (Array.isArray(v) ? v : []);
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);

const L = {
  ko: {
    title: '에어리어 메뉴 대조', lead: '고객 에어리어 메뉴(SE43)의 TCode를 사용 실적과 이 문서의 Task에 대조한 결과입니다.',
    menu: '메뉴', entries: '메뉴 항목', tcodes: 'TCode', core: '사용 · 문서화됨', gap: '사용 · 문서에 없음', dead: '메뉴에만 있음 (미사용)',
    unmeasured: '실적 미측정', offMenu: '메뉴 밖에서 사용', gapTitle: '사용 중이지만 이 문서에 Task가 없는 메뉴 TCode',
    gapLead: '다음 버전에서 Task로 배치할 후보입니다.', tree: '메뉴 트리', folder: '폴더', text: '메뉴 텍스트', usage: '사용', task: 'Task',
    offTitle: '어느 메뉴에도 없는 사용 TCode', offLead: '직접 호출하거나 다른 메뉴(역할 메뉴 등)에서 실행하는 TCode입니다.',
    used: '사용', unused: '미사용', unm: '미측정', menuPath: '에어리어 메뉴', window: '실적 기준',
  },
  en: {
    title: 'Area menu cross-check', lead: 'TCodes of the customer area menu (SE43) checked against usage and against the tasks of this document.',
    menu: 'Menu', entries: 'Menu entries', tcodes: 'TCodes', core: 'Used · documented', gap: 'Used · not documented', dead: 'Menu only (unused)',
    unmeasured: 'Not measured', offMenu: 'Used outside the menu', gapTitle: 'Menu TCodes in use without a task in this document',
    gapLead: 'Candidates to place as tasks in the next version.', tree: 'Menu tree', folder: 'Folder', text: 'Menu text', usage: 'Usage', task: 'Task',
    offTitle: 'Used TCodes in no menu', offLead: 'Run directly or from another menu (e.g. a role menu).',
    used: 'used', unused: 'unused', unm: 'not measured', menuPath: 'Area menu', window: 'Usage window',
  },
  ja: {
    title: 'エリアメニュー照合', lead: '顧客エリアメニュー (SE43) の TCode を利用実績と本書のタスクに照合した結果です。',
    menu: 'メニュー', entries: 'メニュー項目', tcodes: 'TCode', core: '利用 · 記載あり', gap: '利用 · 記載なし', dead: 'メニューのみ (未使用)',
    unmeasured: '実績未測定', offMenu: 'メニュー外で利用', gapTitle: '利用中だが本書にタスクがないメニュー TCode',
    gapLead: '次の版でタスクに配置する候補です。', tree: 'メニューツリー', folder: 'フォルダ', text: 'メニューテキスト', usage: '利用', task: 'タスク',
    offTitle: 'どのメニューにもない利用 TCode', offLead: '直接実行、または別メニュー (ロールメニューなど) から実行されています。',
    used: '利用', unused: '未使用', unm: '未測定', menuPath: 'エリアメニュー', window: '実績基準',
  },
};
export const menuLabels = (lang) => L[lang] || L.en;

const mark = (T, u) => (u === 'used' ? `<span class="mu used">● ${esc(T.used)}</span>` : u === 'unused' ? `<span class="mu unused">○ ${esc(T.unused)}</span>` : `<span class="mu unm">– ${esc(T.unm)}</span>`);
const taskLinks = (m, codes) => arr(codes).map((c) => {
  const r = m.rows.find((x) => x.code === c);
  return `<a href="#${anchorId(c)}" title="${esc(r?.label || '')}">${esc(c)}</a>`;
}).join(' ');
const tbl = (head, rows) => `<div class="tw"><table><thead><tr>${head.map((h) => `<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map((r) => `<tr>${r.map((c) => `<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;

/** Task sheet head row: [label, html] or null. */
export function menuHeadRow(m, row) {
  if (!m.menu || !arr(row.menuPaths).length) return null;
  const T = menuLabels(m.lang);
  return [T.menuPath, arr(row.menuPaths).map((p) => `<code>${esc(p)}</code>`).join('<br>')];
}

/** Appendix section (h3 + content) or ''. */
export function menuSection(m) {
  const mm = m.menu;
  if (!mm || !arr(mm.entries).length) return '';
  const T = menuLabels(m.lang);
  const c = mm.counts || {};
  const menus = arr(mm.menus).map((x) => `<code>${esc(x.menu)}</code>${x.title ? ` ${esc(x.title)}` : ''}${arr(x.menusRead).length > 1 ? ` (+ ${arr(x.menusRead).slice(1).map(esc).join(', ')})` : ''}`).join(' · ');
  const win = arr(mm.usage).map((u) => `${esc(u.system)} ${esc(u.measuredAt || '')}${u.coverage ? ` · ${esc(u.coverage)}/${esc(u.months)}` : ''}`)[0] || '';
  const out = [`<h3 id="amenu">${esc(T.title)}</h3><p class="lead">${esc(T.lead)}</p>`];
  out.push(tbl([T.menu, T.entries, T.tcodes, T.core, T.gap, T.dead, T.unmeasured, T.offMenu, T.window],
    [[menus, esc(c.entries ?? ''), esc(c.tcodes ?? ''), esc(c.core ?? ''), esc(c.gap ?? ''), esc(c.dead ?? ''), esc(c.unmeasured ?? ''), esc(c.offMenu ?? ''), win]]));
  const byT = new Map(arr(mm.entries).map((e) => [e.t, e]));
  if (arr(mm.quadrants?.gap).length) {
    out.push(`<h4 id="amenu-gap">${esc(T.gapTitle)} (${mm.quadrants.gap.length})</h4><p class="lead">${esc(T.gapLead)}</p>`);
    out.push(tbl([T.tcodes, T.text, T.folder], mm.quadrants.gap.map((t) => {
      const e = byT.get(t) || {};
      return [`<code>${esc(t)}</code>`, esc(e.x || ''), esc([e.m, ...arr(e.p)].join(' > '))];
    })));
  }
  // tree: one <details> per top folder, rows in menu order
  const groups = new Map();
  for (const e of arr(mm.entries)) {
    const top = `${e.m} > ${arr(e.p)[0] ?? ''}`;
    if (!groups.has(top)) groups.set(top, []);
    groups.get(top).push(e);
  }
  out.push(`<h4 id="amenu-tree">${esc(T.tree)}</h4>`);
  for (const [top, es] of groups) {
    const used = es.filter((e) => e.u === 'used').length;
    out.push(`<details class="amenu"><summary><b>${esc(top)}</b> · ${es.length} ${esc(T.tcodes)} · ● ${used}</summary>`
      + tbl([T.folder, T.tcodes, T.text, T.usage, T.task], es.map((e) => [esc(arr(e.p).slice(1).join(' > ')), `<code>${esc(e.t)}</code>`, esc(e.x || ''), mark(T, e.u), taskLinks(m, e.r)]))
      + '</details>');
  }
  if (arr(mm.quadrants?.offMenu).length) {
    const off = mm.quadrants.offMenu;
    out.push(`<h4 id="amenu-off">${esc(T.offTitle)} (${off.length})</h4><p class="lead">${esc(T.offLead)}</p><p>${off.map((t) => `<code>${esc(t)}</code>`).join(' ')}</p>`);
  }
  return out.join('');
}

export const MENU_CSS = '.mu.used{color:var(--ok,#1a7f37)}.mu.unused{color:var(--muted,#888)}.mu.unm{color:var(--muted,#888)}details.amenu{margin:.4em 0}details.amenu>summary{cursor:pointer}';

#!/usr/bin/env node
// Area menu × usage × process model (module-to-process, see skills/module-to-process/workflow-menu.md).
//
//   node area-menu.mjs --menu <GetAreaMenu.json> [--menu …] --usage <usage.json|used.txt> [--usage …]
//                      [--model <process-model.json>] --out <menu.json> [--apply] [--hints <menu-hints.json>]
//                      [--add-scope <tcodes-all.json>]
//
// --menu       GetAreaMenu result (inline JSON or the file written with output: "file")
// --usage      saved usage list ({system, measuredAt, measured[], used[]}) or a plain used-TCode list (.txt);
//              TCodes in no `measured` list (and in no .txt) count as unmeasured
// --model      process model: every menu TCode is matched to the L4 rows carrying it (row / variant tcodes)
// --apply      write model.menu + row.menuPaths into the model (backup <model>.bak-menu first)
// --hints      write {tcode: [paths]} for the Step 4 analyst brief
// --add-scope  append menu TCodes missing from tcodes-all.json with packageName "_MENU" (Step 2)
//
// Quadrants: core (menu, used, in model) · gap (menu, used, not in model) · dead (menu, measured, unused)
// · unmeasured (menu, never measured) · offMenu (used model TCodes no menu carries).
import { copyFileSync, existsSync, readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const arr = (v) => (Array.isArray(v) ? v : []);
const SEP = ' > ';

function args(argv) {
  const out = { menu: [], usage: [] };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === '--apply') out.apply = true;
    else if (a === '--menu' || a === '--usage') out[a.slice(2)].push(argv[++i]);
    else if (a.startsWith('--')) out[a.slice(2)] = argv[++i];
  }
  return out;
}

const readJson = (f) => JSON.parse(readFileSync(f, 'utf8').replace(/^﻿/, ''));

export function loadUsage(files) {
  const used = new Set();
  const measured = new Set();
  const sources = [];
  for (const f of files) {
    if (/\.txt$/i.test(f)) {
      for (const t of readFileSync(f, 'utf8').split(/\s+/).filter(Boolean)) {
        used.add(t.toUpperCase());
        measured.add(t.toUpperCase());
      }
      sources.push({ file: f });
      continue;
    }
    const j = readJson(f);
    for (const t of arr(j.measured)) measured.add(String(t).toUpperCase());
    for (const t of arr(j.used)) { used.add(String(t).toUpperCase()); measured.add(String(t).toUpperCase()); }
    // usage.json of a scope dir: {tcodes: {result: {TCODE: bool}}}
    for (const [t, v] of Object.entries(j.tcodes?.result ?? {})) {
      measured.add(t.toUpperCase());
      if (v) used.add(t.toUpperCase());
    }
    sources.push({ file: f, system: j.system, measuredAt: j.measuredAt, months: j.months, coverage: j.coverage });
  }
  return { used, measured, sources };
}

/** tcode → L4 row codes (row and variant TCodes). */
export function modelIndex(model) {
  const idx = new Map();
  for (const r of arr(model?.rows)) {
    if (r.level !== 4) continue;
    const tcs = [...arr(r.tcodes), ...arr(r.variants).flatMap((v) => arr(v.tcodes))];
    for (const t of tcs) {
      const k = String(t).toUpperCase();
      if (!idx.has(k)) idx.set(k, []);
      if (!idx.get(k).includes(r.code)) idx.get(k).push(r.code);
    }
  }
  return idx;
}

export function crossMenu(menus, usage, model) {
  const idx = modelIndex(model);
  const entries = [];
  for (const mres of menus) {
    for (const e of arr(mres.entries)) {
      const t = String(e.tcode).toUpperCase();
      const u = usage.used.has(t) ? 'used' : usage.measured.has(t) ? 'unused' : 'unmeasured';
      entries.push({ tcode: t, text: e.text || '', path: arr(e.path), menu: e.menu || mres.menu, usage: u, rows: idx.get(t) || [] });
    }
  }
  const uniq = (xs) => [...new Set(xs)].sort();
  const menuSet = new Set(entries.map((e) => e.tcode));
  const pick = (f) => uniq(entries.filter(f).map((e) => e.tcode));
  const quadrants = {
    core: pick((e) => e.usage === 'used' && e.rows.length),
    gap: pick((e) => e.usage === 'used' && !e.rows.length),
    dead: pick((e) => e.usage === 'unused'),
    unmeasured: pick((e) => e.usage === 'unmeasured'),
    offMenu: uniq([...idx.keys()].filter((t) => !menuSet.has(t) && usage.used.has(t))),
  };
  return {
    kind: 'area-menu',
    menus: menus.map((m) => ({ menu: m.menu, title: m.title || '', menusRead: arr(m.menus_read), links: arr(m.links) })),
    usage: usage.sources.map(({ system, measuredAt, months, coverage }) => ({ system, measuredAt, months, coverage })).filter((s) => s.system),
    counts: {
      entries: entries.length,
      tcodes: menuSet.size,
      ...Object.fromEntries(Object.entries(quadrants).map(([k, v]) => [k, v.length])),
    },
    quadrants,
    entries,
  };
}

/** model.menu (compact) + row.menuPaths. Returns the number of rows annotated. */
export function applyToModel(model, result) {
  const paths = new Map();
  for (const e of result.entries) {
    const p = [e.menu, ...e.path].join(SEP);
    for (const code of e.rows) {
      if (!paths.has(code)) paths.set(code, new Set());
      paths.get(code).add(`${p}${SEP}${e.tcode}`);
    }
  }
  let n = 0;
  for (const r of arr(model.rows)) {
    if (r.level !== 4) continue;
    const ps = paths.get(r.code);
    if (ps?.size) { r.menuPaths = [...ps]; n++; } else delete r.menuPaths;
  }
  model.menu = {
    menus: result.menus.map(({ menu, title, menusRead }) => ({ menu, title, menusRead })),
    usage: result.usage,
    counts: result.counts,
    quadrants: { gap: result.quadrants.gap, offMenu: result.quadrants.offMenu },
    entries: result.entries.map((e) => ({ t: e.tcode, x: e.text, p: e.path, m: e.menu, u: e.usage, r: e.rows })),
  };
  return n;
}

function main() {
  const a = args(process.argv.slice(2));
  if (!a.menu.length || !a.out) {
    console.error('usage: area-menu.mjs --menu <GetAreaMenu.json> --usage <file> [--model <model>] --out <menu.json> [--apply] [--hints <file>] [--add-scope <tcodes-all.json>]');
    process.exit(2);
  }
  const menus = a.menu.map(readJson).map((j) => (j.output === 'file' && j.path ? readJson(j.path) : j));
  for (const m of menus) if (!Array.isArray(m.entries)) throw new Error(`${m.menu ?? '?'}: no entries — pass the full GetAreaMenu result`);
  const usage = loadUsage(a.usage);
  const model = a.model ? readJson(a.model) : null;
  const result = crossMenu(menus, usage, model);
  writeFileSync(a.out, JSON.stringify(result, null, 1));
  if (a.hints) {
    const hints = {};
    for (const e of result.entries) (hints[e.tcode] ||= []).push([e.menu, ...e.path].join(SEP));
    writeFileSync(a.hints, JSON.stringify(hints, null, 1));
  }
  if (a['add-scope']) {
    const all = readJson(a['add-scope']);
    const have = new Set(all.map((x) => String(x.name ?? x.tcode ?? '').toUpperCase()));
    const add = [...new Set(result.entries.map((e) => e.tcode))].filter((t) => !have.has(t));
    for (const t of add) all.push({ name: t, type: 'TRAN/T', packageName: '_MENU', description: '' });
    writeFileSync(a['add-scope'], JSON.stringify(all, null, 1));
    result.counts.addedToScope = add.length;
  }
  if (a.apply) {
    if (!model) throw new Error('--apply needs --model');
    if (!existsSync(`${a.model}.bak-menu`)) copyFileSync(a.model, `${a.model}.bak-menu`);
    result.counts.rowsAnnotated = applyToModel(model, result);
    writeFileSync(a.model, JSON.stringify(model, null, 1));
  }
  console.log(JSON.stringify(result.counts));
}

const thisFile = fileURLToPath(import.meta.url);
if (process.argv[1] && resolve(process.argv[1]) === thisFile) main();

