cd C:/Users/pssps/Documents/Projects/sc4sap_project/.sc4sap/work/HKT-DEV/processes && node -e "
const fs=require('fs');
const lab=(m)=>{const x=new Map();for(const r of m.rows)x.set(r.code,r.label);return x};
for(const [A,B] of [['SD','LE'],['MM','LE']]){
 const ma=require('./'+A+'/_state/process-model.json'),mb=require('./'+B+'/_state/process-model.json');const la=lab(ma),lb=lab(mb);const L={[A]:la,[B]:lb};
 const tp=require('./_integration/'+A+'-'+B+'/_state/integration-touchpoints.json').touchpoints;
 const out=['# '+A+'↔'+B+' digest','','The reference graph found no task pairs (the '+B+' tasks run mostly standard WM TCodes, so their writes are not in the graph). Build scenarios from the task maps, the touchpoints to '+B+' objects below and the analyst hand-off notes.',''];
 out.push('## Touchpoints to / from '+B);
 const rel=tp.filter(x=>x.owner===B||x.from.module===B);const g=new Map();
 for(const x of rel){const k=x.from.module+' '+x.from.code+' '+(L[x.from.module].get(x.from.code)||'');if(!g.has(k))g.set(k,[]);g.get(k).push(x.object+'('+x.role+(x.owner?'→'+x.owner:'')+')')}
 for(const[k,v]of g)out.push('- '+k+' | '+[...new Set(v)].join(', '));
 out.push('','## Hand-off notes (crossModule) naming '+A+'/'+B+'/WM');
 for(const [M,m] of [[A,ma],[B,mb]])for(const c of m.crossModule||[]){const s=JSON.stringify(c);if((c.from===B||c.to===B||c.to==='WM'||c.from==='WM'||(M===B&&(c.to===A||c.from===A))))out.push('- ['+M+'] '+(c.from||'')+'→'+(c.to||'')+' '+(c.object||'')+': '+(c.desc||''))}
 for(const [M,m] of [[A,ma],[B,mb]]){out.push('','## '+M+' map — L2 / L3 / L4');for(const r of m.rows.filter(r=>r.level>=2))out.push('  '.repeat(r.level-2)+r.code+' '+r.label+(r.level==4&&r.tcodes?' ['+r.tcodes.slice(0,6).join(' ')+']':''))}
 fs.writeFileSync('_integration/'+A+'-'+B+'/_state/digest.md',out.join('\n'));console.log(A+'-'+B,out.length,'lines')}"

